// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        address admin = address(0x1);
        vm.prank(admin);
        c.initialize(admin); // using admin as dummy lrtConfig address (not used in this test)

        // Set maxNodeDelegatorCount to 5
        vm.prank(admin);
        c.updateMaxNodeDelegatorCount(5);

        // Attempt to add 6 node delegators (should revert in reference, succeed in mutant)
        address[] memory newDelegators = new address[](6);
        for (uint i = 0; i < 6; i++) {
            newDelegators[i] = address(uint160(i + 1));
        }

        bool ok = false;
        vm.prank(admin);
        try c.addNodeDelegatorContractToQueue(newDelegators) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference should revert (ok = false), mutant should succeed (ok = true)
        assertTrue(!ok, "Expected revert due to exceeding maxNodeDelegatorCount");
    }
}

