        c.initialize(address(this));

        // Set maxNodeDelegatorCount to 5
        c.updateMaxNodeDelegatorCount(5);

        // Prepare 6 addresses to add
        address[] memory delegators = new address[](6);
        for (uint i = 0; i < 6; i++) {
            delegators[i] = address(uint160(i + 1));
        }

        // Try to add 6 delegators; should revert in reference (limit 5) but succeed in buggy version
        bool ok;
        try c.addNodeDelegatorContractToQueue(delegators) {
            ok = true;
        } catch {
