pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Initialize the contract as admin would
        address admin = address(0x1);
        vm.prank(admin);
        c.initialize(admin); // lrtConfigAddr set to admin for simplicity; we use admin as the only role

        // 2. Grant admin the DEFAULT_ADMIN_ROLE and MANAGER role to call onlyLRTAdmin/onlyLRTManager functions
        // We'll use vm.prank to simulate admin calls directly

        // 3. Add one node delegator first (empty contract address for simplicity, but it must be non-zero)
        address nodeDelegator = address(0x2);
        address[] memory firstBatch = new address[](1);
        firstBatch[0] = nodeDelegator;
        vm.prank(admin);
        c.addNodeDelegatorContractToQueue(firstBatch);

        // 4. Now call updateMaxNodeDelegatorCount via onlyLRTAdmin (admin is the 0x00 role holder)
        vm.prank(admin);
        c.updateMaxNodeDelegatorCount(10);

        // 5. Now try to add 10 more node delegators: this should revert on reference (10 + 1 > 10) but not on bug (bug sets maxNodeDelegatorCount to 0)
        address[] memory secondBatch = new address[](10);
        for(uint i = 0; i < 10; i++) {
            secondBatch[i] = address(uint160(0x100 + i));
        }
        bool ok = false;
        vm.prank(admin);
        try c.addNodeDelegatorContractToQueue(secondBatch) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: maxNodeDelegatorCount = 10, queue length = 1, adding 10 would make 11 > 10 => revert => ok = false
        // Bug: maxNodeDelegatorCount = 0, queue length = 1, adding 10 => 11 > 0 => condition false, so it proceeds => ok = true
        // We assert on the reference behavior: ok should be false
        assertTrue(!ok);
    }
}

